// Part "roofs": the eight roofs (plan.md ROOFS). Plot 0's hip is roof.json, laid by runParts right after the shell; the
// other seven are laid here by the roof tool, one per plot, with the chimney stacks and the other plots' wall tops kept.
import { roof } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

// keep boxes as { from, to }: the chimney stacks (y0..20) and anything a part builds above the eave that must stay
const stack = (x0, z0, x1, z1) => ({ from: [x0, 0, z0], to: [x1, 20, z1] });

export function build(g) {
  // plot 0 Magnolia: low hip over the two storeys (plan ROOFS; the roof.json file was never written, so the plot had none).
  // The portico's pediment is the porch part's; the chimney stacks pass through the eaves, kept.
  roof(g, [2, 13, 13, 21], "hip", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 9, pitch: 45, material: "deepslate_tiles", overhang: 1,
    // the chimney stacks, and the attic room's headroom (x5..10, y10..11, z15..19; rooms.json) with the ladder column x11 left
    // as air under the hip; the roof above y12 still carries the ridge
    keep: [stack(0, 16, 2, 18), stack(13, 16, 15, 18), { from: [5, 10, 15], to: [11, 11, 19] }],
  });

  // plot 1 Alhambra: front-gabled low roof behind the shaped parapet (ridge along z), red-tile, eaves on the sides only.
  // No fascia: the spruce trapdoors would hang off the corners of the eave with nothing behind them.
  roof(g, [18, 13, 29, 21], "gable", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 9, ridgeAxis: "z", pitch: "half", material: "bricks", overhang: { north: 0, south: 1, east: 1, west: 1 },
    keep: [{ from: [18, 9, 13], to: [29, 14, 13] }, stack(26, 21, 28, 23)],
  });

  // plot 2 Vallonia: side-gabled cottage sweeping down over the full-width porch (ridge along x)
  roof(g, [35, 9, 45, 21], "cottage", { texture: false, fascia: "spruce", soffit: "spruce",
    y: 5, ridgeAxis: "x", material: "spruce_planks", verge: "birch_planks", overhang: 1,
    keep: [stack(33, 16, 35, 18)],
  });

  // plot 3 Puritan: gambrel, ridge along x, steep lower course, shallow upper, long front shed dormer
  roof(g, [51, 13, 61, 21], "gambrel", { texture: false, fascia: "spruce", soffit: "spruce",
    // no overhang over the front (north, z12): its eave drops to y3 across the entry porch's headroom and the shutters
    y: 5, ridgeAxis: "x", pitch: 2, upperPitch: "half", lower: 2, material: "deepslate_tiles", verge: "dark_oak_planks", overhang: { north: 0, south: 1, east: 1, west: 1 },
    steep: true, dormers: { face: "north", style: "shed", width: 7, count: 1 },
    keep: [stack(49, 16, 51, 18), { from: [51, 5, 13], to: [51, 10, 21] }, { from: [61, 5, 13], to: [61, 10, 21] }],
  });

  // plot 4 Cornell: low hip, wide eaves, hipped dormer on the front, and the hip porch roof over the full-width porch
  // plain eave and soffit, no fascia (plan ROOFS); the wide eave's end would otherwise float past the plot
  roof(g, [67, 13, 77, 21], "hip", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 9, pitch: 45, material: "deepslate_tiles", overhang: 2,
    dormers: { face: "north", style: "hip", count: 1, width: 5 },
    keep: [stack(77, 16, 79, 18)],
  });
  roof(g, [67, 9, 77, 12], "hip", { texture: false, fascia: "spruce", soffit: "spruce",
    // no overhang front or back (z8, z13): the eave would drop to y3 over the ramp's headroom (z7..8) and the front wall's
    // door and sidelight cells; the sides keep theirs
    y: 5, pitch: 45, material: "deepslate_tiles", overhang: { north: 0, south: 0, east: 1, west: 1 },
    keep: [{ from: [67, 5, 13], to: [77, 8, 13] }],
  });

  // plot 5 Stanford: steep side gable with two gabled dormers on the front
  roof(g, [83, 14, 93, 21], "cottage", { texture: false, fascia: "spruce", soffit: "spruce",
    y: 7, ridgeAxis: "x", pitch: 45, material: "deepslate_tiles", verge: "smooth_quartz", overhang: 1,
    dormers: { face: "north", count: 2, style: "gable", width: 3 },
    // the side gable walls (shell) already stand at x 83 and 93 up the rake: the roof leaves those cells to them
    keep: [stack(87, 17, 89, 19), { from: [83, 6, 14], to: [83, 9, 21] }, { from: [93, 6, 14], to: [93, 9, 21] }],
  });

  // plot 6 Winona: front gable, ridge along z at x 104 (gable end to the street)
  roof(g, [100, 13, 108, 22], "gable", { texture: false, fascia: "spruce", soffit: "spruce",
    y: 5, ridgeAxis: "z", pitch: 45, material: "spruce_planks", verge: "birch_planks", overhang: 1,
    // the front and back gable triangles are the shell's sandstone infill: the roof leaves them to the walls
    keep: [stack(108, 17, 110, 19), { from: [100, 5, 13], to: [108, 9, 13] }, { from: [100, 5, 22], to: [108, 9, 22] }],
  });

  // plot 7 Craftsman: front gable with wide eaves and a half pitch, dark slate; the porch roof is a shed low to the north
  // no fascia: its east end at x 128 would be outside the site (the build grows to 129) and float
  roof(g, [114, 13, 125, 21], "gable", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 9, ridgeAxis: "z", pitch: "half", material: "deepslate_tiles", verge: "dark_oak_planks", overhang: 2,
    // the gable triangles at z 13 and z 21 are the shell's spruce_planks upper storey: the roof leaves them to the walls
    keep: [stack(125, 16, 127, 18), { from: [114, 9, 13], to: [125, 13, 13] }, { from: [114, 9, 21], to: [125, 13, 21] }],
  });
  roof(g, [114, 9, 125, 12], "shed", { texture: false, edges: { fascia: false }, soffit: "spruce",
    y: 5, pitch: "half", material: "deepslate_tiles", overhang: 1,
    keep: [{ from: [114, 5, 13], to: [125, 8, 13] }],
  });
}
// Part "chimneys, walks and grounds" (plan.md PARTS 6): the accessible walk and ramp to every main door, the lawn and the
// hedge on each plot, foundation planting in the front lawn row, the porch lanterns, and the eight chimneys (chimneyStack
// with the plan's calls). Runs after the roofs, porches and fittings, so every write here is into air or ground.
import { lawn, hedge, foundationPlanting, porchLantern, chimneyStack } from "../vocab.mjs";
import { SITE_SIZE } from "../vocab/base.mjs";

// per plot: the walk's first absolute x and width (plan.md SITE), the deck material (plan.md MATERIALS) and the deck's z
// span: the ramp is two cells (z deckZ0-2..deckZ0-1), the walk runs from z5 to the ramp, the deck ends at the cell in front of the door
const WALKS = [
  { x: 6, w: 4, deckZ0: 9, deckZ1: 12, deck: "smooth_quartz" },   // plot 0 Magnolia (walk 6..9)
  { x: 23, w: 2, deckZ0: 9, deckZ1: 12, deck: "mud_bricks" },     // plot 1 Alhambra (walk 23..24)
  { x: 39, w: 3, deckZ0: 9, deckZ1: 12, deck: "spruce_planks" },  // plot 2 Vallonia (walk 39..41)
  { x: 55, w: 3, deckZ0: 10, deckZ1: 12, deck: "smooth_quartz" }, // plot 3 Puritan (walk 55..57, ramp 8..9)
  { x: 71, w: 3, deckZ0: 9, deckZ1: 12, deck: "oak_planks" },     // plot 4 Cornell (walk 71..73)
  { x: 87, w: 3, deckZ0: 12, deckZ1: 13, deck: "smooth_stone" },  // plot 5 Stanford (walk 87..89, ramp 10..11, landing 12..13)
  { x: 103, w: 3, deckZ0: 10, deckZ1: 12, deck: "oak_planks" },   // plot 6 Winona (walk 103..105, ramp 8..9)
  { x: 118, w: 3, deckZ0: 9, deckZ1: 12, deck: "spruce_planks" }, // plot 7 Craftsman (walk 118..120)
];

// chimney calls (plan.md): wall cell at floor y 1, the room side (into), the flue's last course (top). The shell leaves the
// mouths unset (not air), so the chimney's mouth and lintel are written like any other cell of the stack
const CHIMNEYS = [
  { wall: [2, 1, 17], into: "east", top: 15 },
  { wall: [13, 1, 17], into: "west", top: 15 },
  { wall: [27, 1, 21], into: "north", top: 14 },
  { wall: [35, 1, 17], into: "east", top: 14 },
  { wall: [51, 1, 17], into: "east", top: 14 },
  { wall: [77, 1, 17], into: "west", top: 15 },
  { at: [88, 1, 18], open: "south", top: 13 },
  { wall: [108, 1, 18], into: "west", top: 11 },
  { wall: [125, 1, 17], into: "west", top: 15 },
];

// porch lanterns, hung under a porch ceiling block (porchLantern refuses a lantern with nothing above it)
const LANTERNS = [
  [5, 8, 10], [10, 8, 10],        // plot 0 under the portico entablature
  [56, 4, 10],                    // plot 3 under the pediment entablature, by the door
  [70, 4, 12], [74, 4, 12],       // plot 4 under the square porch's hip roof, each side of the door
  [103, 4, 11], [105, 4, 11],     // plot 6 under the gable porch eave, each side of the door
  [117, 4, 11], [121, 4, 11],     // plot 7 under the broad porch, each side of the door
];

// the walk and ramp to a door (plan.md SITE): smooth_stone walk flush at y0 over the grass, two bottom slabs at y1 for the
// ramp, then the deck block at y1. accessRamp() only writes into air, and the walk's cells are grass, so it refuses the
// whole way; this writes the walk over the ground (the ground part's grass is still writable here) and the ramp and deck
// into air only, so a porch deck already laid stays as it is.
function walkAndRamp(g, { x, w, deckZ0, deckZ1, deck }) {
  for (let dx = 0; dx < w; dx++) {
    const X = x + dx;
    for (let z = 5; z <= deckZ0 - 3; z++) g.set(X, 0, z, "smooth_stone");
    for (let z = deckZ0 - 2; z <= deckZ0 - 1; z++) if (g.isAir(X, 1, z)) g.set(X, 1, z, "smooth_stone_slab", { type: "bottom" });
    for (let z = deckZ0; z <= deckZ1; z++) if (g.isAir(X, 1, z)) g.set(X, 1, z, deck);
  }
}

// the cells above the ground that earlier parts built, read as this part starts (y1 up; the ground is still writable).
// runParts refuses any write into them, so a chimney must not try: the roof's stair where a stack passes through it,
// the room's floor under a hearth. Air the shell left is not in the set, so the flue and mouth stay writable.
function builtBefore(g) {
  const [SX, SY, SZ] = SITE_SIZE;
  const taken = new Set();
  for (let x = 0; x < SX; x++) for (let y = 1; y < SY; y++) for (let z = 0; z < SZ; z++) if (!g.isAir(x, y, z)) taken.add(`${x},${y},${z}`);
  return taken;
}

// one chimney. Its writes into cells an earlier part built are dropped (taken, see builtBefore); the rest of the stack,
// the mouth and the lintel over it included, is laid as usual.
function chimneyAt(g, c, taken) {
  const view = {
    get: (...a) => g.get(...a),
    inBounds: (...a) => g.inBounds(...a),
    isAir: (...a) => g.isAir(...a),
    set: (x, y, z, ...rest) => {
      if (taken.has(`${x},${y},${z}`)) return null;
      return g.set(x, y, z, ...rest);
    },
  };
  return chimneyStack(view, { ...c, hay: true });
}

export function build(g) {
  // read before any write of this part: the cells the earlier parts built
  const taken = builtBefore(g);
  // the walk and ramp first: the lawn writes only into what is still air or grass, so it leaves their cells alone
  WALKS.forEach((w) => walkAndRamp(g, w));
  for (let plot = 0; plot < 8; plot++) {
    lawn(g, plot);
    hedge(g, { x0: 16 * plot, w: 16, z: 24 });
    const w = WALKS[plot];
    // planting on the front lawn row z8, never on the walk and ramp columns
    foundationPlanting(g, { x0: 16 * plot + 1, x1: 16 * plot + 14, z: 8, skip: [[w.x, w.x + w.w - 1]] });
  }
  for (const [x, y, z] of LANTERNS) porchLantern(g, { x, y, z });
  // street lamps: a standing lantern on a fence post on each sidewalk (z3), two per plot, clear of every walk and ramp;
  // they light the street and the walks
  for (let plot = 0; plot < 8; plot++) for (const x of [16 * plot + 4, 16 * plot + 12]) {
    g.set(x, 1, 3, "spruce_fence");
    g.set(x, 2, 3, "lantern", { hanging: "false" });
  }
  for (const c of CHIMNEYS) chimneyAt(g, c, taken);
}
// Part "porches and facade ornament": porches, decks, pedimented and gabled entries, arcades, parapets and the
// porch-side ornament of all eight plots (plan.md FACADES, ROOFS for the porch roofs, SITE for the ramps).
// Everything here is built into air only; the shell, roofs and walks are earlier parts and stay locked.
import {
  portico, balcony, shapedParapet, arcadeBay, rafterTails, pedimentPorch, squarePorch,
  doorHood, gablePorch,
} from "../vocab.mjs";
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // ---- plot 0 Magnolia: full-height portico (4 quartz columns, pediment) and the balcony over the door ----
  portico(g, { x0: 4, x1: 11, z0: 9, z1: 12, deck: "smooth_quartz", column: "quartz_pillar", trim: "smooth_quartz", rake: "quartz" });
  balcony(g, { x0: 6, x1: 9, z0: 10, z1: 12, y: 5, floor: "smooth_quartz", rail: "iron_bars" });

  // ---- plot 1 Alhambra: shaped parapet on the front wall, arcaded porch with a flat deck and red-tile pent ----
  shapedParapet(g, {
    z: 13,
    steps: [[9, 18, 29], [10, 19, 28], [11, 20, 27], [12, 21, 26], [13, 22, 25], [14, 23, 24]],
    piers: 10, vent: { x0: 23, x1: 24, y: 11 }, body: "white_terracotta", coping: "brick",
  });
  arcadeBay(g, { x0: 19, x1: 22, z: 9, y: 2 });
  arcadeBay(g, { x0: 22, x1: 25, z: 9, y: 2 });
  arcadeBay(g, { x0: 25, x1: 28, z: 9, y: 2 });
  g.fill([19, 1, 9], [28, 1, 12], "mud_bricks");            // porch deck (the piers stand on it)
  g.fill([19, 5, 9], [28, 5, 12], "mud_bricks");            // flat deck over the arcade
  for (const x of [19, 28]) {                                 // side walls with an arch each, z10..11
    g.fill([x, 2, 10], [x, 4, 12], "white_terracotta");
    g.fill([x, 2, 10], [x, 3, 11], "air");
    g.fill([x, 4, 10], [x, 4, 11], "bricks");
  }
  for (let x = 19; x <= 28; x++) g.set(x, 5, 8, ...B.stairs("brick", "south", "bottom"));  // the pent, rising to the house

  // ---- plot 2 Vallonia: tapered piers, porch ceiling, deck, rafter tails over the front eave ----
  // the roof sweep already fills the beam row (y5 z9), so the piers stop at the taper post under it
  for (const x of [35, 38, 42, 45]) roofedPier(g, { x, z: 9, stone: "cobblestone", post: "spruce" });
  g.fill([35, 1, 9], [45, 1, 12], "spruce_planks");          // deck (the piers stand on it)
  g.fill([35, 4, 10], [45, 4, 12], "spruce_slab", { type: "top" });   // porch ceiling, clear of the posts
  for (const [a, b] of [[36, 37], [39, 41], [43, 44]]) g.fill([a, 4, 9], [b, 4, 9], "spruce_slab", { type: "top" });
  rafterTails(g, { x0: 35, x1: 45, z: 8, y: 5, into: "south", wood: "spruce" });

  // ---- plot 3 Puritan: pedimented entry porch, two quartz columns ----
  pedimentPorch(g, { x0: 55, x1: 57, z0: 10, z1: 12, y: 1, facing: "north", trim: "quartz" });

  // ---- plot 4 Cornell: full-width square-columned porch ----
  squarePorch(g, { x0: 67, x1: 77, z0: 9, z1: 12, column: "smooth_quartz", pier: "bricks", frieze: "smooth_quartz", deck: "oak_planks" });

  // ---- plot 5 Stanford: door hood over the centred door, landing before it ----
  doorHood(g, { x0: 87, x1: 89, z: 13, y: 5, trim: "smooth_quartz" });
  g.fill([87, 1, 12], [89, 1, 13], "smooth_stone");          // landing (the ramp runs z10..11 into it)

  // ---- plot 6 Winona: small gabled porch on birch posts ----
  gablePorch(g, { x0: 102, x1: 106, z0: 10, z1: 12, deck: "oak_planks", column: "stripped_birch", roof: "spruce", verge: "birch", infill: "smooth_sandstone" });

  // ---- plot 7 Craftsman: broad porch on stone piers, deck ----
  // the porch roof (roofs part) fills the beam row y5 z9, so the piers stop at the taper post under it
  for (const x of [114, 117, 122, 125]) roofedPier(g, { x, z: 9, stone: "cobblestone", post: "spruce" });
  g.fill([114, 1, 9], [125, 1, 12], "spruce_planks");
}

// A pier whose beam row is already the roof's: stone y2..3 and the taper post at y4, nothing at y5 (the roof's cell)
function roofedPier(g, { x, z, stone, post }) {
  g.fill([x, 2, z], [x, 3, z], stone);
  g.set(x, 4, z, ...B.fence(post));
}
The owner's review of v1, house by house (plot numbers as in plan.md). Keep the Alhambra (plot 1) and the Craftsman (plot 7) as they are.
- Plot 0 Magnolia: the roof has an open hole at the back (a bed shows through from above): close it. The two chimneys are far oversized: make them ordinary stacks (1x1 flue in a 2-wide or 3-wide brick stack) set into the end walls. Add the three front dormers the plan gives it. The portico stair at 6,11,9 and 9,11,9 ends a step short (fit): flush the top step.
- Plot 2 Vallonia: it reads as a steep wooden A-frame; it must read as a low Craftsman bungalow. Rebuild its roof: a LOW side gable (about 1 up in 2 across), dark shingle, that sweeps on down over a full-width front porch at the same pitch, with a wide shed dormer on the front slope; tapered wooden porch posts on stone piers; exposed rafter tails under the eaves. One and a half storeys, not a tall gable wall facing the street.
- Plot 3 Puritan: make the gambrel read: a steep lower slope (nearly vertical, 2-3 courses) breaking to a shallow upper slope, on both sides, with the long shed dormer across the front; replace the tall white entry block with a small entry hood on two columns. Close the 1-wide gap in the entry porch.
- Plot 4 Cornell: it reads one storey; it must read as a two-storey foursquare: two full storeys of walls with the upper windows under the eaves, the low hipped roof and hipped dormer on top, and a full-width one-storey porch with square columns across the front.
- Plot 5 Stanford / Cape Cod: add the two gabled dormers on the front slope; the central chimney's hearth needs its mouth open into the room at floor level.
- Plot 6 Winona: the chimney stands in the middle of the front; move it to a side wall (an exterior chimney with the hearth inside). Keep the porch under the front gable.
- Fit: the campfire at 88,1,18 is shut inside its stack: give it the hearth mouth into the room.
Every house keeps its plot, its slab-ramp way in, its beds and its rooms; change only what is listed.
