input.command:
cd /Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/sears-kit; date; python3 - <<'EOF'
p='parts/roofs.mjs'
s=open(p).read()
# magnolia: close hole + dormers (after the hip call: find end of plot 0 roof call)
marker="  // plot 1 Alhambra"
add='''  // plot 0 Magnolia, after the hip: the attic keep box left the roof open along its front and back rows (y11, z15 and z19, x5..11):
  // close them with the hip's own stairs, then three small gabled dormers on the north slope (x3..5, x7..8, x10..12)
  for (let x = 5; x <= 11; x++) {
    g.set(x, 11, 15, ...B.stairs("deepslate_tile", "south"));
    g.set(x, 11, 19, ...B.stairs("deepslate_tile", "north"));
  }
  const wall = "white_concrete";
  for (const [x0, x1, cheeks] of [[3, 5, true], [7, 8, false], [10, 12, true]]) {
    const lo = cheeks ? x0 : x0 - 1, hi = cheeks ? x1 : x1 + 1;
    for (let x = lo; x <= hi; x++) {
      const pane = cheeks ? x > x0 && x < x1 : x >= x0 && x <= x1;
      for (const y of [10, 11]) {
        if (!cheeks && !pane && y === 10) continue;           // the middle dormer's cheeks stand on the roof stairs at y11 only
        if (pane) g.set(x, y, 14, "glass_pane", { east: "true", west: "true" }); else g.set(x, y, 14, wall);
      }
      if (x === lo) g.set(x, 12, 14, ...B.stairs("deepslate_tile", "east"));
      else if (x === hi) g.set(x, 12, 14, ...B.stairs("deepslate_tile", "west"));
      else g.set(x, 12, 14, "deepslate_tiles");
    }
    for (let x = x0; x <= x1; x++) if (x >= 4 && x <= 11) g.set(x, 12, 15, "deepslate_tiles");
  }

'''
s=s.replace(marker,add+marker,1)
# stanford dormers + winona chimney keep
s=s.replace("keep: [stack(108, 17, 110, 19), { from: [100, 5, 13]","keep: [stack(98, 17, 99, 19), { from: [100, 5, 13]")
marker="  // plot 6 Winona"
add='''  // plot 5 Stanford: two small gabled dormers (x85..87, x89..91) on the front slope, a 1x2 window each at x86 / x90 (y8..9)
  for (const cx of [86, 90]) {
    for (const x of [cx - 1, cx + 1]) for (const z of [15, 16]) for (const y of [8, 9]) g.set(x, y, z, "calcite");
    for (const y of [8, 9]) g.set(cx, y, 15, "glass_pane", { east: "true", west: "true" });
    for (const y of [8, 9]) for (const z of [15, 16]) if (!(y === 8 && z === 16)) g.set(cx, y, z, "air");
    for (const z of [15, 16]) {
      g.set(cx - 1, 10, z, ...B.stairs("deepslate_tile", "east"));
      g.set(cx + 1, 10, z, ...B.stairs("deepslate_tile", "west"));
      g.set(cx, 10, z, z === 15 ? "calcite" : "deepslate_tiles");
    }
  }

'''
s=s.replace(marker,add+marker,1)
open(p,'w').write(s)

p='parts/shell-east.mjs'
s=open(p).read()
s=s.replace("  cut(h, [108], [1, 2], [18]);                      // hearth mouth\n","  cut(h, [100], [1, 2], [18]);                      // hearth mouth (west wall, the chimney moved off the east side)\n")
open(p,'w').write(s)

p='parts/grounds.mjs'
s=open(p).read()
s=s.replace('{ wall: [108, 1, 18], into: "west", top: 11 }','{ wall: [100, 1, 18], into: "east", top: 7 }')
s=s.replace('{ wall: [2, 1, 17], into: "east", top: 15 }','{ wall: [2, 1, 17], into: "east", top: 11 }').replace('{ wall: [13, 1, 17], into: "west", top: 15 }','{ wall: [13, 1, 17], into: "west", top: 11 }')
open(p,'w').write(s)

p='parts/porches.mjs'
s=open(p).read()
s=s.replace("  balcony(g, {","  // flush the pediment's top step: the peak is two stairs meeting back to back, not a full block a jump above the rakes\n  g.set(7, 12, 9, ...B.stairs(\"quartz\", \"east\"));\n  g.set(8, 12, 9, ...B.stairs(\"quartz\", \"west\"));\n  balcony(g, {",1)
open(p,'w').write(s)

p='parts/room-46.mjs'
s=open(p).read()
s=s.replace('    "b      ", // z18: barrel; the hearth front stays clear','    "       ", // z18: the west hearth front stays clear (the chimney moved here from the east wall)')
s=s.replace('    "M      ", // z18: and on the barrel beside it','    "       ", // z18')
open(p,'w').write(s)
EOF
grep -n "108\|east hearth" parts/room-46.mjs parts/fittings.mjs | head; sh make.sh 2>&1 | grep -i "refused\|error" | head -5

